#!/usr/bin/env python3
"""Pasang sinkronisasi Supabase ke index.html kasir ngoombé.
Pemakaian:  python3 patch-sync.py index.html
Hasil: index.html diperbarui (cadangan lama disimpan sebagai index.html.bak)."""
import sys, shutil

path = sys.argv[1] if len(sys.argv) > 1 else 'index.html'
src = open(path, encoding='utf-8').read()
if 'Sinkronisasi Supabase' in src:
    sys.exit('File ini sudah berisi sinkronisasi Supabase.')

BLOCK = "/* ================= Sinkronisasi Supabase ================= */\nlet sb = null, channel = null, knownReady = false;\nlet queue = {tx:[], del:[], settings:false};\ntry { Object.assign(queue, JSON.parse(localStorage.getItem(QKEY)||'{}')); } catch(e){}\nconst knownTx = new Set();\nlet lastSettings = '', flushing = false, flushT = null, pullT = null, pulling = false, pullAgain = false;\nconst OWNER_EMAIL = OWNER_USER + '@' + EMAIL_DOMAIN;\nconst saveQ = () => { try{ localStorage.setItem(QKEY, JSON.stringify(queue)); }catch(e){} };\nconst settingsPayload = () => ({store:state.store, allocations:state.allocations, profitShare:state.profitShare, products:state.products});\nconst pendingCount = () => queue.tx.length + queue.del.length + (queue.settings ? 1 : 0);\nconst chunk = (a, n) => { const r = []; for (let i=0; i<a.length; i+=n) r.push(a.slice(i, i+n)); return r; };\n\nfunction setSync(m){\n  const el = $('#sync-label'); if (!el) return;\n  const n = pendingCount();\n  const map = {\n    ok:['Tersinkron','ok'], sync:['Menyinkronkan…','sync'],\n    off:['Offline' + (n ? ' · ' + n + ' antre' : ''),'off'],\n    err:['Gagal sinkron' + (n ? ' · ' + n + ' antre' : ''),'err']\n  };\n  const v = map[m];\n  el.className = 'sync' + (v ? ' ' + v[1] : '');\n  el.innerHTML = v ? '<i></i>' + v[0] : '';\n  el.title = 'Ketuk untuk sinkron sekarang';\n}\n\n/* Deteksi perubahan (restore, hapus, reset, ubah pengaturan) lalu antrekan */\nfunction trackChanges(){\n  if (!session.role) return;\n  if (knownReady){\n    const ids = new Set(state.transactions.map(t => t.id));\n    state.transactions.forEach(t => { if (!knownTx.has(t.id) && !queue.tx.includes(t.id)) queue.tx.push(t.id); });\n    if (session.role === 'owner'){\n      knownTx.forEach(id => { if (!ids.has(id) && !queue.del.includes(id)) queue.del.push(id); });\n      if (JSON.stringify(settingsPayload()) !== lastSettings) queue.settings = true;\n    }\n  }\n  queue.tx = queue.tx.filter(id => state.transactions.some(t => t.id === id));\n  saveQ();\n  setSync(navigator.onLine ? 'sync' : 'off');\n  clearTimeout(flushT); flushT = setTimeout(flush, 350);\n}\n\nasync function flush(){\n  if (!sb || !session.role) return;\n  if (flushing) return;\n  flushing = true; setSync('sync');\n  const owner = session.role === 'owner';\n  try {\n    if (owner && queue.settings){\n      const payload = settingsPayload();\n      const r = await sb.from('app_settings').upsert({id:1, data:payload, updated_at:new Date().toISOString()});\n      if (r.error) throw r.error;\n      lastSettings = JSON.stringify(payload); queue.settings = false; saveQ();\n    }\n    if (queue.tx.length){\n      const rows = queue.tx.map(id => state.transactions.find(t => t.id === id)).filter(Boolean).map(t => ({id:t.id, ts:t.ts, data:t}));\n      for (const part of chunk(rows, 200)){\n        const r = await sb.from('transactions').upsert(part, {onConflict:'id', ignoreDuplicates:true});\n        if (r.error) throw r.error;\n        part.forEach(x => knownTx.add(x.id));\n        const done = new Set(part.map(x => x.id)); queue.tx = queue.tx.filter(id => !done.has(id)); saveQ();\n      }\n      queue.tx = queue.tx.filter(id => state.transactions.some(t => t.id === id));\n    }\n    if (owner && queue.del.length){\n      for (const part of chunk(queue.del.slice(), 100)){\n        const r = await sb.from('transactions').delete().in('id', part);\n        if (r.error) throw r.error;\n        part.forEach(id => knownTx.delete(id));\n        queue.del = queue.del.filter(id => !part.includes(id)); saveQ();\n      }\n    }\n    saveQ(); setSync('ok');\n  } catch(e){\n    console.warn('Sinkron gagal', e); saveQ(); setSync(navigator.onLine ? 'err' : 'off');\n  }\n  flushing = false;\n  if (pullAgain){ pullAgain = false; pull(); }\n}\n\n/* Ambil data terbaru dari server */\nasync function pull(){\n  if (!sb || !session.role) return;\n  if (flushing || pulling){ pullAgain = true; return; }\n  pulling = true;\n  try {\n    const sres = await sb.from('app_settings').select('data').eq('id', 1).maybeSingle();\n    if (sres.error) throw sres.error;\n    const rows = [];\n    for (let from = 0; ; from += 1000){\n      const r = await sb.from('transactions').select('data').order('ts', {ascending:true}).order('id', {ascending:true}).range(from, from + 999);\n      if (r.error) throw r.error;\n      rows.push(...r.data);\n      if (r.data.length < 1000) break;\n    }\n    const owner = session.role === 'owner';\n    const server = new Map(rows.map(r => [r.data.id, r.data]));\n    /* Pertama kali perangkat ini terhubung: kirim transaksi lama yang masih lokal */\n    let migrated = false; try { migrated = !!localStorage.getItem(MIGKEY); } catch(e){}\n    if (!migrated){\n      state.transactions.forEach(t => { if (!server.has(t.id) && !queue.tx.includes(t.id)) queue.tx.push(t.id); });\n      try { localStorage.setItem(MIGKEY, '1'); } catch(e){}\n    }\n    const local = new Map(state.transactions.map(t => [t.id, t]));\n    const next = [];\n    server.forEach((t, id) => { if (!queue.del.includes(id)) next.push(t); });\n    queue.tx.forEach(id => { if (!server.has(id) && local.has(id)) next.push(local.get(id)); });\n    next.sort((a, b) => a.ts - b.ts);\n    state.transactions = next;\n    knownTx.clear(); server.forEach((_, id) => knownTx.add(id));\n    queue.tx = queue.tx.filter(id => local.has(id));\n\n    const sd = sres.data && sres.data.data;\n    if (sd && Array.isArray(sd.products)){\n      if (!(owner && queue.settings)){\n        state.store = Object.assign(defaults().store, sd.store || {});\n        if (Array.isArray(sd.allocations)) state.allocations = sd.allocations;\n        if (Array.isArray(sd.profitShare)) state.profitShare = sd.profitShare;\n        state.products = sd.products;\n        lastSettings = JSON.stringify(settingsPayload());\n      }\n    } else if (owner){\n      queue.settings = true; /* server masih kosong: isi dari data perangkat ini */\n    }\n    knownReady = true;\n    try { localStorage.setItem(KEY, JSON.stringify(state)); } catch(e){}\n    saveQ();\n    const typing = ui.tab === 'pengaturan' && /INPUT|SELECT/.test(document.activeElement ? document.activeElement.tagName : '');\n    if (!draft && !typing) renderAll();\n    if (pendingCount()){ setSync('sync'); pulling = false; flush(); }\n    else setSync('ok');\n  } catch(e){\n    console.warn('Gagal mengambil data', e); setSync(navigator.onLine ? 'err' : 'off');\n  }\n  pulling = false;\n  if (pullAgain && !flushing){ pullAgain = false; pull(); }\n}\n\nfunction startRealtime(){\n  if (!sb) return;\n  if (channel){ try { sb.removeChannel(channel); } catch(e){} channel = null; }\n  const sched = () => { clearTimeout(pullT); pullT = setTimeout(pull, 500); };\n  channel = sb.channel('ngoombe-sync')\n    .on('postgres_changes', {event:'*', schema:'public', table:'transactions'}, sched)\n    .on('postgres_changes', {event:'*', schema:'public', table:'app_settings'}, sched)\n    .subscribe();\n}\n\nasync function enterCloud(user){\n  const owner = (user.email || '').toLowerCase() === OWNER_EMAIL;\n  session = owner ? {role:'owner', label:'Owner'} : {role:'karyawan', label:'Karyawan'};\n  try { localStorage.setItem(SESSION_KEY, JSON.stringify({role:session.role})); } catch(e){}\n  $('#login').classList.remove('open');\n  renderAll(); setSync('sync');\n  startRealtime();\n  await pull();\n}\nasync function cloudLogin(u, pw){\n  const err = $('#login-err'); err.textContent = '';\n  if (!sb){ err.textContent = 'Tidak bisa memuat Supabase. Periksa internet lalu muat ulang halaman.'; return; }\n  const email = u.includes('@') ? u : u + '@' + EMAIL_DOMAIN;\n  const btn = $('#login-form button[type=submit]'); btn.disabled = true;\n  try {\n    const r = await sb.auth.signInWithPassword({email, password:pw});\n    if (r.error){\n      err.textContent = /fetch|network/i.test(r.error.message) ? 'Tidak ada koneksi internet.' : 'Username atau password salah.';\n      $('#lg-pass').select(); return;\n    }\n    $('#lg-pass').value = '';\n    await enterCloud(r.data.user);\n    toast('Masuk sebagai ' + session.label);\n  } catch(e){\n    err.textContent = 'Tidak bisa terhubung ke server.';\n  } finally { btn.disabled = false; }\n}\nfunction cloudLogout(){\n  if (!CLOUD) return;\n  if (channel && sb){ try { sb.removeChannel(channel); } catch(e){} channel = null; }\n  knownReady = false; knownTx.clear(); setSync('');\n  if (sb) sb.auth.signOut().catch(()=>{});\n}\nasync function boot(){\n  try { if (window.supabase) sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY, {auth:{persistSession:true, autoRefreshToken:true}}); } catch(e){ console.warn(e); }\n  let user = null;\n  if (sb){ try { const r = await sb.auth.getSession(); user = r.data.session && r.data.session.user; } catch(e){} }\n  if (user) return enterCloud(user);\n  /* Buka aplikasi saat offline: pakai peran login terakhir, data dari cache perangkat */\n  try {\n    const sv = JSON.parse(localStorage.getItem(SESSION_KEY) || 'null');\n    if (sv && sv.role && !navigator.onLine){\n      session = {role:sv.role, label: sv.role === 'owner' ? 'Owner' : 'Karyawan'};\n      renderAll(); setSync('off'); return;\n    }\n  } catch(e){}\n  showLogin();\n}\nif (CLOUD){\n  window.addEventListener('online', () => { if (!sb) return location.reload(); flush(); pull(); });\n  window.addEventListener('offline', () => { if (session.role) setSync('off'); });\n  document.addEventListener('visibilitychange', () => { if (!document.hidden && sb && session.role){ flush(); pull(); } });\n  setInterval(() => { if (sb && session.role && !document.hidden) pull(); }, 60000);\n  document.addEventListener('click', e => { if (e.target.closest('#sync-label') && sb && session.role){ flush(); pull(); } });\n}\n\n"

CSS = """.sync{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:600;color:var(--muted);cursor:pointer;white-space:nowrap}
.sync i{width:8px;height:8px;border-radius:50%;background:var(--muted);display:inline-block}
.sync.ok i{background:#2E9E5B}.sync.sync i{background:var(--mango)}.sync.err i{background:var(--danger)}
/* ---------- Responsive ---------- */"""

CONFIG = """const CASHIER_KEY = 'ngoombe-nama-kasir';
/* ---- Supabase: isi dua baris ini (lihat README). Kosong = mode lokal ---- */
const SUPABASE_URL = '';
const SUPABASE_KEY = '';
const OWNER_USER = 'aderiza';
const EMAIL_DOMAIN = 'ngoombe.app';
const CLOUD = !!(SUPABASE_URL && SUPABASE_KEY);
const QKEY = 'ngoombe-antrian', MIGKEY = 'ngoombe-migrasi';"""

edits = [
 ('/* ---------- Responsive ---------- */', CSS),
 ('<div class="who"><span class="role" id="role-label"></span>',
  '<div class="who"><span class="sync" id="sync-label"></span><span class="role" id="role-label"></span>'),
 ('<script>\n/* ================= Util ================= */',
  '<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.45.4/dist/umd/supabase.js"></script>\n<script>\n/* ================= Util ================= */'),
 ("const CASHIER_KEY = 'ngoombe-nama-kasir';", CONFIG),
 ("catch(e){ toast('Data tidak bisa disimpan di browser ini', 'err'); }\n}",
  "catch(e){ toast('Data tidak bisa disimpan di browser ini', 'err'); }\n  if (CLOUD) trackChanges();\n}"),
 ("state.transactions.push(txn); save();",
  "state.transactions.push(txn); if (CLOUD && !queue.tx.includes(txn.id)) queue.tx.push(txn.id); save();"),
 ("session = {}; try{ localStorage.removeItem(SESSION_KEY); }catch(e){} ui.cart = [];",
  "session = {}; try{ localStorage.removeItem(SESSION_KEY); }catch(e){} cloudLogout(); ui.cart = [];"),
 ("try { const sv = JSON.parse(localStorage.getItem(SESSION_KEY)||'null'); const u = sv && USERS.find",
  "if (!CLOUD) try { const sv = JSON.parse(localStorage.getItem(SESSION_KEY)||'null'); const u = sv && USERS.find"),
 ("const u = $('#lg-user').value.trim().toLowerCase(), pw = $('#lg-pass').value;",
  "const u = $('#lg-user').value.trim().toLowerCase(), pw = $('#lg-pass').value;\n  if (CLOUD){ cloudLogin(u, pw); return; }"),
 ("if (session.role) renderAll(); else showLogin();",
  "if (CLOUD) boot(); else if (session.role) renderAll(); else showLogin();"),
 ("/* ================= Login ================= */", BLOCK + "/* ================= Login ================= */"),
 ("Data tersimpan di browser perangkat ini. Unduh cadangan secara rutin supaya aman, dan pakai cadangan itu untuk memindahkan data ke perangkat lain.",
  "Data tersinkron ke database online dan sama di semua perangkat yang login (kalau Supabase belum diisi, data hanya di browser ini). Unduh cadangan secara rutin sebagai arsip."),
 ("Hapus SEMUA riwayat transaksi? Menu dan harga tetap ada.",
  "Hapus SEMUA riwayat transaksi di semua perangkat? Menu dan harga tetap ada."),
 ("Reset semua data ke awal? Menu, pos alokasi, dan transaksi akan hilang.",
  "Reset semua data ke awal di semua perangkat? Menu, pos alokasi, dan transaksi akan hilang."),
]
for old, new in edits:
    n = src.count(old)
    if n != 1:
        sys.exit('Gagal: bagian berikut ditemukan %d kali (harus 1):\n%s' % (n, old[:90]))
    src = src.replace(old, new)

shutil.copyfile(path, path + '.bak')
open(path, 'w', encoding='utf-8').write(src)
print('Selesai. Sekarang isi SUPABASE_URL dan SUPABASE_KEY di index.html.')
